<div class="alert alert-info">Konfigurasi per jenis tagihan. Jika <strong>Tidak</strong>, pembayaran tidak otomatis masuk ke Pemasukan dan dapat dicatat manual di menu Keuangan.</div><div class="card"><div class="card-header app-card-header d-flex justify-content-between align-items-center flex-wrap gap-2"><h4 class="header-title mb-0">Pengaturan Integrasi Pemasukan</h4><button type="button" id="btn-add" class="btn btn-sm btn-outline-primary"><i class="ri-add-line"></i> Tambah</button></div><div class="card-body"><div class="row mb-3"><div class="col-md-5"><input id="cari" class="form-control" placeholder="Cari data ..."></div></div><div id="data-list"></div></div></div>
<div class="modal fade" id="modalSetting" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 id="modal-title" class="modal-title">Pengaturan Integrasi Pemasukan</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><form id="settings-form"><div class="modal-body"><div class="row g-3"><div class="col-md-12"><label class="form-label">Jenis Tagihan</label><select class="form-select" name="id_jenis_tagihan" required></select></div><div class="col-md-6"><label class="form-label">Masuk Pemasukan</label><select class="form-select" name="integrasi_pemasukan" ><option value="Tidak">Tidak</option><option value="Ya">Ya</option></select></div><div class="col-md-6"><label class="form-label">Pos Penerimaan</label><select class="form-select" name="id_kode_akun" ></select></div><div class="col-md-12"><label class="form-label">Kas/Bank</label><select class="form-select" name="id_kasbank" ></select></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Batal</button><button id="btn-save" type="submit" class="btn btn-primary">Simpan</button></div></form></div></div></div>

<script>
(function(){
const base=<?= json_encode(site_url('admin/spp/integrasi_pemasukan/')) ?>;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $id=id=>document.getElementById(id); let rows=[];
const form=$id('settings-form');
function alertError(x){Swal.fire('Gagal',x?.responseJSON?.message||'Gagal memproses data','error');}
function load(){ $.post(base+'data',{}, r=>{rows=r.data||[];render();},'json').fail(alertError); }
function fill(row){form.reset(); if(row)form.elements.namedItem('id_jenis_tagihan').value=row.id;Object.keys(row||{}).forEach(k=>{let el=form.elements.namedItem(k);if(el&&row[k]!=null) el.value=row[k];}); form.elements.namedItem('id_jenis_tagihan').disabled=false; form.elements.namedItem('integrasi_pemasukan').dispatchEvent(new Event('change')); $id('modal-title').textContent=(row?'Edit':'Tambah')+' Integrasi Pemasukan'; bootstrap.Modal.getOrCreateInstance($id('modalSetting')).show();}
function render(){const q=$id('cari').value.trim().toLowerCase();let filtered=rows.filter(r=>Object.values(r).some(x=>String(x??'').toLowerCase().includes(q)));$id('data-list').innerHTML=filtered.length?filtered.map((r,i)=>`<div class="card-mapel"><p class="keterangan-hari">${esc(r.tipe_default)}</p><div class="keterangan-mapel"><div class="keterangan-mapel-kiri"><h5 class="judul-mapel">${i+1}. ${esc(r.nama_jenis)}</h5><p class="keterangan-jam-mapel">${'Masuk Pemasukan: '+esc(r.integrasi_pemasukan)+' | Pos: '+esc(r.nama_akun||'-')+' | Kas/Bank: '+esc(r.nama_kasbank||'-')}</p></div><div class="keterangan-mapel-kanan"><button type="button" class="btn btn-sm btn-outline-warning" data-edit="${i}"><i class="ri-edit-line me-1"></i>Atur</button></div></div></div>`).join(''):'<div class="card-mapel">Tidak ada data.</div>';$id('data-list').querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>fill(filtered[+b.dataset.edit])));}
$id('cari').addEventListener('input',render);
$id('btn-add').classList.add('d-none');
form.addEventListener('submit',function(e){e.preventDefault();$id('btn-save').disabled=true;$.post(base+'simpan',$(form).serialize(),function(r){if(r.result==='true'){bootstrap.Modal.getOrCreateInstance($id('modalSetting')).hide();load();Swal.fire('Berhasil',r.message,'success');}else Swal.fire('Gagal',r.message,'error');},'json').fail(alertError).always(()=>$id('btn-save').disabled=false);});
$.post(base+'opsi',{},o=>{ const accounts=o.akun||[],banks=o.kasbank||[]; form.elements.namedItem('id_kode_akun').innerHTML='<option value="">-- Pilih Pos Penerimaan --</option>'+accounts.map(x=>`<option value="${x.id}">${esc(x.keterangan)}</option>`).join('');form.elements.namedItem('id_kasbank').innerHTML='<option value="">-- Pilih Kas/Bank --</option>'+banks.map(x=>`<option value="${x.id}">${esc(x.keterangan)}</option>`).join('');},'json');
form.elements.namedItem('integrasi_pemasukan').addEventListener('change',e=>{const yes=e.target.value==='Ya';form.elements.namedItem('id_kode_akun').disabled=!yes;form.elements.namedItem('id_kasbank').disabled=!yes;form.elements.namedItem('id_kode_akun').required=yes;form.elements.namedItem('id_kasbank').required=yes;if(!yes){form.elements.namedItem('id_kode_akun').value='';form.elements.namedItem('id_kasbank').value='';}});

$.post(base+'data',{},r=>{rows=r.data||[];form.elements.namedItem('id_jenis_tagihan').innerHTML=rows.map(x=>`<option value="${x.id}">${esc(x.nama_jenis)}</option>`).join('');render();},'json');
})();
</script>
